// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "../FullMath.sol";

/// @notice Fixed-ratio arithmetic for variable inventory. All amounts are integers
///         in the corresponding asset's smallest units, never display prices.
library ADDFixedPriceMathV1 {
    /// @return tokens Token units bought, capped at the remaining sale allocation.
    /// @return principal Native units backing those tokens (rounded upward).
    /// @return fee The existing ADD 1% fee on the actual gross settled amount.
    /// @return refund Unused native payment; always returned to the buyer.
    /// @dev Retain v13 rounding when the full budget is used. Variable, potentially
    ///      tiny allocations may leave a rounding refund even before the last buy:
    ///      in that case charge only on actual settlement, never on returned money.
    function quoteNativeBuy(uint256 payment, uint256 remaining, uint256 allocation, uint256 target)
        internal pure returns (uint256 tokens, uint256 principal, uint256 fee, uint256 refund)
    {
        if (payment == 0 || remaining == 0) return (0, 0, 0, payment);
        fee = payment / 100;
        uint256 spendable = payment - fee;
        uint256 cost = FullMath.mulDivUp(remaining, target, allocation);
        if (spendable >= cost) {
            tokens = remaining;
            principal = cost;
        } else {
            tokens = FullMath.mulDiv(spendable, allocation, target);
            principal = FullMath.mulDivUp(tokens, target, allocation);
        }
        if (principal < spendable) fee = principal / 99;
        if (tokens == 0) fee = 0;
        refund = payment - principal - fee;
    }

    /// @notice Required backing for issued token units, using exact rational math.
    function costUp(uint256 tokens, uint256 allocation, uint256 target) internal pure returns (uint256) {
        return FullMath.mulDivUp(tokens, target, allocation);
    }

    /// @notice Asset amount returned on sale, before the existing BNB-denominated fee.
    function valueDown(uint256 tokens, uint256 allocation, uint256 target) internal pure returns (uint256) {
        return FullMath.mulDiv(tokens, target, allocation);
    }
}

contracts/portal-v1/ADDPortalAccessV1.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title Ownership and enumerable factory admission for the candidate ADD Portal v1.
/// @notice Removing a factory revokes FUTURE admissions only. A derived Portal must
///         never gate an already admitted token's buys/sells on its factory membership.
/// @dev This is a standalone, non-upgradeable module. There is no delegatecall,
///      implementation slot, renounce-owner function, or automatic token admission.
abstract contract ADDPortalAccessV1 {
    error OnlyOwner();
    error OnlyPendingOwner();
    error InvalidOwner();
    error InvalidFactory();
    error FactoryAlreadySupported();
    error FactoryNotSupported();

    address public owner;
    address public pendingOwner;
    address[] private supportedFactories;
    // Index + 1; zero denotes absence. Swap-and-pop does not preserve list order.
    mapping(address => uint256) private factoryIndex;
    mapping(address => bytes32) public factoryCodeHash;

    event OwnershipTransferStarted(address indexed previousOwner, address indexed pendingOwner);
    event OwnershipTransferCancelled(address indexed pendingOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event FactoryAdded(address indexed factory, bytes32 codeHash);
    event FactoryRemoved(address indexed factory);

    modifier onlyOwner() {
        if (msg.sender != owner) revert OnlyOwner();
        _;
    }

    constructor(address initialOwner) {
        if (initialOwner == address(0) || initialOwner == address(this)) revert InvalidOwner();
        owner = initialOwner;
        emit OwnershipTransferred(address(0), initialOwner);
    }

    /// @notice Propose a successor; ownership stays with the current owner until acceptance.
    /// @dev The successor may be an EOA or multisig. No private key is required by this contract.
    function transferOwnership(address successor) external onlyOwner {
        if (successor == address(0) || successor == address(this) || successor == owner) revert InvalidOwner();
        pendingOwner = successor;
        emit OwnershipTransferStarted(owner, successor);
    }

    function cancelOwnershipTransfer() external onlyOwner {
        address cancelled = pendingOwner;
        delete pendingOwner;
        emit OwnershipTransferCancelled(cancelled);
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner || pendingOwner == address(0)) revert OnlyPendingOwner();
        address previous = owner;
        owner = msg.sender;
        delete pendingOwner;
        emit OwnershipTransferred(previous, msg.sender);
    }

    /// @notice Approve a reviewed factory for future admission calls.
    /// @dev Code existence/hash pinning is NOT proof of safe factory behavior. In
    ///      particular an upgradeable factory can change logic without changing its
    ///      proxy code hash. Ownership is explicitly trusted to review admissions.
    function addFactory(address factory) external onlyOwner {
        if (factory == address(this) || factory.code.length == 0) revert InvalidFactory();
        if (factoryIndex[factory] != 0) revert FactoryAlreadySupported();
        _validateFactory(factory);
        supportedFactories.push(factory);
        factoryIndex[factory] = supportedFactories.length;
        factoryCodeHash[factory] = factory.codehash;
        emit FactoryAdded(factory, factory.codehash);
    }

    /// @notice Remove permission to add NEW pools; existing pools are not deleted or repriced.
    function removeFactory(address factory) external onlyOwner {
        uint256 slot = factoryIndex[factory];
        if (slot == 0) revert FactoryNotSupported();
        uint256 last = supportedFactories.length;
        if (slot != last) {
            address moved = supportedFactories[last - 1];
            supportedFactories[slot - 1] = moved;
            factoryIndex[moved] = slot;
        }
        supportedFactories.pop();
        delete factoryIndex[factory];
        delete factoryCodeHash[factory];
        emit FactoryRemoved(factory);
    }

    function isFactorySupported(address factory) public view returns (bool) {
        return factoryIndex[factory] != 0;
    }

    /// @notice Enumerate all currently approved addresses. Order changes on removal.
    function getSupportedFactories() external view returns (address[] memory) {
        return supportedFactories;
    }

    function supportedFactoryCount() external view returns (uint256) {
        return supportedFactories.length;
    }

    function _requireFactory(address factory) internal view {
        if (!isFactorySupported(factory) || factory.codehash != factoryCodeHash[factory]) revert FactoryNotSupported();
    }

    /// @dev The concrete Portal checks the factory's interface version and Portal binding here.
    function _validateFactory(address factory) internal view virtual;
}

contracts/portal-v1/ADDPortalConversionV.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./IADDPortalV1.sol";
import "../FullMath.sol";
import "../openzeppelin/SafeERC20.sol";

interface IADDRecoveryHostV1 {
    function quoteAlternativeGraduation(address token,address asset) external view returns (uint256,uint256,uint256,address[] memory);
    function executeRecoveryStart(address token,address pair,uint256 reserve) external;
    function executeRecoveryFinish(address token,address asset,uint256 received) external;
    function protectedERC20(address asset) external view returns (uint256);
}

/// @notice Fixed, non-upgradeable conversion helper deployed by one Portal.
/// @dev No owner, arbitrary spender/recipient, delegatecall, or asset-withdrawal
///      method. Only its immutable Portal can convert; output always returns there.
///      Separating this implementation keeps Portal below the EIP-170 code limit.
contract ADDPortalConversionV1 {
    using SafeERC20 for IERC20Minimal;
    address public immutable portal;
    address public immutable router;
    address public immutable wrappedNative;
    uint256 public constant SLIPPAGE_BPS = 500;
    error InvalidConversion();
    error InvalidTransfer();
    error InvalidLiquidity();
    error PoolAlreadyInitialized();

    function assertEmptyPair(address token,address asset,address pair) external view {
        if (pair.code.length == 0 || IADDV2FactoryV1(IADDV2RouterV1(router).factory()).getPair(token,asset) != pair)
            revert InvalidLiquidity();
        if (IADDV2PairV1(pair).totalSupply() != 0) revert PoolAlreadyInitialized();
    }

    /// @notice Direct, first-liquidity mint on behalf of the immutable Portal.
    /// @dev Pulls exactly approved amounts straight into the canonical pair. Checks
    ///      balances, reserves and LP recipient; donations/sync without LP are allowed.
    function mintLiquidity(address token,address asset,address pair,uint256 tokenAmount,uint256 quoteAmount)
        external returns (uint256 liquidity)
    {
        if (msg.sender != portal) revert InvalidConversion();
        if (IADDV2FactoryV1(IADDV2RouterV1(router).factory()).getPair(token,asset) != pair) revert InvalidLiquidity();
        IADDV2PairV1 market = IADDV2PairV1(pair);
        if (market.totalSupply() != 0) revert PoolAlreadyInitialized();
        uint256 t = IERC20Minimal(token).balanceOf(pair);
        uint256 q = IERC20Minimal(asset).balanceOf(pair);
        if (quoteAmount == 0 || tokenAmount > type(uint112).max || quoteAmount > type(uint112).max
            || t > type(uint112).max-tokenAmount || q > type(uint112).max-quoteAmount) revert InvalidLiquidity();
        uint256 portalT = IERC20Minimal(token).balanceOf(portal);
        uint256 portalQ = IERC20Minimal(asset).balanceOf(portal);
        IERC20Minimal(asset).safeTransferFrom(portal,pair,quoteAmount);
        IERC20Minimal(token).safeTransferFrom(portal,pair,tokenAmount);
        address dead = 0x000000000000000000000000000000000000dEaD;
        uint256 lpBefore = market.balanceOf(dead);
        liquidity = market.mint(dead);
        if (liquidity == 0 || market.balanceOf(dead) != lpBefore+liquidity
            || IERC20Minimal(token).balanceOf(pair) != t+tokenAmount || IERC20Minimal(asset).balanceOf(pair) != q+quoteAmount
            || IERC20Minimal(token).balanceOf(portal)+tokenAmount != portalT
            || IERC20Minimal(asset).balanceOf(portal)+quoteAmount != portalQ) revert InvalidLiquidity();
        (uint112 r0,uint112 r1,) = market.getReserves();
        bool first = market.token0() == token;
        if (uint256(first?r0:r1) != t+tokenAmount || uint256(first?r1:r0) != q+quoteAmount) revert InvalidLiquidity();
    }

    constructor(address router_) {
        portal = msg.sender;
        router = router_;
        wrappedNative = IADDV2RouterV1(router_).WETH();
    }

    function minimumOut(uint256 quoted) public pure returns (uint256) {
        return FullMath.mulDivUp(quoted,9500,10000);
    }

    function quote(address from,address to,uint256 amount) public view
        returns (uint256 expected,uint256 minimum,address[] memory path)
    {
        from = from == address(0) ? wrappedNative : from;
        to = to == address(0) ? wrappedNative : to;
        if (from == to || amount == 0) revert InvalidConversion();
        path = new address[](from == wrappedNative || to == wrappedNative ? 2 : 3);
        path[0] = from;
        if (path.length == 3) path[1] = wrappedNative;
        path[path.length-1] = to;
        uint256[] memory amounts = IADDV2RouterV1(router).getAmountsOut(amount,path);
        if (amounts.length != path.length || amounts[0] != amount) revert InvalidConversion();
        expected = amounts[amounts.length-1];
        if (expected == 0) revert InvalidConversion();
        minimum = minimumOut(expected);
    }

    /// @dev Portal wraps BNB before approving this helper. Exact balance deltas on
    ///      BOTH custody transfers and output reject taxed/rebasing assets. Any
    ///      unrelated helper dust is preserved. Approvals are cleared on success
    ///      and restored by transaction rollback on failure.
    function convert(address from,address to,uint256 amount,uint256 signedMinimum,uint256 deadline)
        external returns (uint256 received,uint256 effectiveMinimum)
    {
        if (msg.sender != portal || signedMinimum == 0 || block.timestamp > deadline) revert InvalidConversion();
        return _convert(from,to,amount,signedMinimum,deadline);
    }

    /// @dev The Portal's owner-only, nonReentrant entry is the sole caller. Host
    ///      callbacks accept only this immutable engine. No user-selectable host,
    ///      router, spender, recipient, or arbitrary external call exists.
    function graduateAlternative(address token,address newAsset,uint256 expectedReserve,uint256 signedQuote,uint256 deadline)
        external returns (uint256 received,uint256 effectiveMinimum)
    {
        if (msg.sender != portal || signedQuote == 0 || block.timestamp > deadline) revert InvalidConversion();
        IADDRecoveryHostV1 host = IADDRecoveryHostV1(portal);
        (uint256 reserve,,uint256 minimum,address[] memory path) = host.quoteAlternativeGraduation(token,newAsset);
        if (reserve != expectedReserve) revert InvalidConversion();
        uint256 signedMinimum = minimumOut(signedQuote);
        if (signedMinimum > minimum) minimum = signedMinimum;
        address factory = IADDV2RouterV1(router).factory();
        address output = path[path.length-1];
        address pair = IADDV2FactoryV1(factory).getPair(token,output);
        if (pair == address(0)) pair = IADDV2FactoryV1(factory).createPair(token,output);
        uint256 outputBefore = IERC20Minimal(output).balanceOf(portal);
        if (outputBefore < host.protectedERC20(output)) revert InvalidTransfer();
        host.executeRecoveryStart(token,pair,reserve);
        (received,effectiveMinimum) = _convert(path[0],output,reserve,minimum,deadline);
        host.executeRecoveryFinish(token,newAsset,received);
        if (IERC20Minimal(output).balanceOf(portal) != outputBefore) revert InvalidTransfer();
    }

    function _convert(address from,address to,uint256 amount,uint256 signedMinimum,uint256 deadline)
        internal returns (uint256 received,uint256 effectiveMinimum)
    {
        (,uint256 currentMinimum,address[] memory path) = quote(from,to,amount);
        effectiveMinimum = signedMinimum > currentMinimum ? signedMinimum : currentMinimum;
        IERC20Minimal input = IERC20Minimal(path[0]);
        IERC20Minimal output = IERC20Minimal(path[path.length-1]);
        uint256 inputBefore = input.balanceOf(address(this));
        uint256 portalBefore = input.balanceOf(portal);
        uint256 outputBefore = output.balanceOf(portal);
        input.safeTransferFrom(portal,address(this),amount);
        if (input.balanceOf(address(this)) != inputBefore + amount || input.balanceOf(portal) + amount != portalBefore)
            revert InvalidTransfer();
        input.safeApprove(router,0);
        input.safeApprove(router,amount);
        uint256[] memory amounts = IADDV2RouterV1(router).swapExactTokensForTokens(amount,effectiveMinimum,path,portal,deadline);
        input.safeApprove(router,0);
        received = output.balanceOf(portal) - outputBefore;
        if (received < effectiveMinimum || amounts.length != path.length || amounts[0] != amount
            || amounts[amounts.length-1] != received || input.balanceOf(address(this)) != inputBefore
            || input.balanceOf(portal) + amount != portalBefore) revert InvalidTransfer();
    }
}

contracts/portal-v1/ADDPortalLedgerV1.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ADDPortalAccessV1.sol";
import "./ADDPortalQuoterV1.sol";
import "./IADDPortalV1.sol";
import "../openzeppelin/SafeERC20.sol";
import "../openzeppelin/ReentrancyGuard.sol";

/// @title Variable-inventory, multi-asset fixed-price ledger for candidate Portal v1.
/// @notice Each admission snapshots actual UNENCUMBERED token inventory once.
///         Subsequent donations never alter price, inventory allocation, or progress.
/// @dev Owner withdrawals are surplus-only, including during active fundraising.
///      There is deliberately NO emergency path capable of withdrawing backing.
abstract contract ADDPortalLedgerV1 is ADDPortalAccessV1, ReentrancyGuard {
    using SafeERC20 for IERC20Minimal;
    uint256 public constant DEPLOYMENT_VERSION = 1;
    uint256 public constant DEFAULT_TARGET_BNB = 4 ether;
    uint256 public constant MIN_TARGET_BNB = 1 ether;
    address public constant LP_BURN_ADDRESS = 0x000000000000000000000000000000000000dEaD;

    // Append states to preserve the original public numeric values (Graduated=3).
    enum Phase { Unlisted, Active, Migrating, Graduated, GraduationFailed, RefundOnly, Refunded }
    struct Pool {
        address factory; // Zero for an explicit owner listing of an external token.
        address creator;
        address quoteAsset;
        address pair;
        uint256 initialInventory;
        uint256 saleAllocation;
        uint256 liquidityAllocation;
        uint256 sold;
        uint256 reserve; // Quote-asset units, NOT necessarily BNB wei.
        uint256 targetBNB;
        uint256 quoteTarget;
        uint8 quoteDecimals;
        bool customTarget;
        bool lifecycleHooks;
        Phase phase;
    }
    struct BuyQuote {
        uint256 tokens;
        uint256 principal; // Quote-asset contribution.
        uint256 nativeUsed; // BNB consumed to acquire principal, excluding ADD fee.
        uint256 fee;
        uint256 refund;
    }

    ADDPortalQuoterV1 public immutable quoteHelper;
    address public immutable router;
    address public immutable dexFactory;
    address public immutable wrappedNative;
    address public feeRecipient;
    bool public customTargetsEnabled;
    /// @notice Separate owner opt-in. Solidity initializes this to false regardless
    ///         of the constructor's custom-target setting. Never gates existing pools.
    bool public externalDepositsEnabled;
    mapping(address => Pool) internal pools;
    uint256 public totalNativeReserved;
    // Aggregate obligations in EACH ERC20, including both launch inventory AND
    // reserves of OTHER pools using that ERC20 as their quote asset. Never subtract
    // only one role when listing an external token or recovering a surplus.
    mapping(address => uint256) public protectedERC20;

    error InvalidAdmission();
    error AlreadyListed();
    error UnexpectedInventory();
    error InvalidTarget();
    error CustomTargetsClosed();
    error ExternalDepositsClosed();
    error QuoteChanged();
    error UnsupportedAsset();
    error PoolAlreadyInitialized();
    error InvalidPair();
    error PoolNotActive();
    error TradeExpired();
    error InvalidAmount();
    error SlippageExceeded();
    error UnsupportedTransfer();
    error InsufficientBacking();
    error InsufficientSurplus();
    error NativeTransferFailed();
    error InvalidRecipient();
    error OnlySelf();

    event PoolRegistered(address indexed token,address indexed factory,address indexed creator,address quoteAsset,
        address pair,uint256 inventory,uint256 saleAllocation,uint256 liquidityAllocation,uint256 targetBNB,uint256 quoteTarget,bool customTarget,string metadataURI);
    event Buy(address indexed token,address indexed buyer,uint256 payment,uint256 tokens,uint256 quotePrincipal,uint256 nativePrincipal,uint256 fee,uint256 refund);
    event Sell(address indexed token,address indexed seller,uint256 tokens,uint256 quotePrincipal,uint256 nativeGross,uint256 fee,uint256 nativeNet);
    event CustomTargetsEnabled(bool enabled);
    event ExternalDepositsEnabled(bool enabled);
    event ExternalDepositListed(address indexed token,address indexed caller,uint256 inventory);
    event FeeRecipientChanged(address indexed previousRecipient,address indexed newRecipient);
    event SurplusWithdrawn(address indexed asset,address indexed recipient,uint256 requestedAmount);

    constructor(address initialOwner,address router_,address feeRecipient_,bool customEnabled)
        ADDPortalAccessV1(initialOwner)
    {
        if (router_.code.length == 0) revert UnsupportedAsset();
        address dex = IADDV2RouterV1(router_).factory();
        address wrapped = IADDV2RouterV1(router_).WETH();
        if (dex.code.length == 0 || wrapped.code.length == 0) revert UnsupportedAsset();
        router = router_;
        quoteHelper = new ADDPortalQuoterV1(router_);
        dexFactory = dex;
        wrappedNative = wrapped;
        _validRecipient(feeRecipient_);
        feeRecipient = feeRecipient_;
        customTargetsEnabled = customEnabled;
    }

    /// @notice Direct BNB deposits are unassigned surplus, never a buy or reserve top-up.
    /// @dev Router conversion proceeds also arrive here; the caller's guarded swap
    ///      accounts only for its observed delta, not the Portal's aggregate balance.
    receive() external payable {}

    function getPool(address token) external view returns (Pool memory) { return pools[token]; }

    function setCustomTargetsEnabled(bool enabled) external onlyOwner {
        customTargetsEnabled = enabled;
        emit CustomTargetsEnabled(enabled);
    }

    /// @notice Open/close permissionless external deposits. This is an explicit
    ///         exception to factory-only automatic admission; review external tokens
    ///         independently of factory-issued tokens in indexers and website UI.
    function setExternalDepositsEnabled(bool enabled) external onlyOwner {
        externalDepositsEnabled = enabled;
        emit ExternalDepositsEnabled(enabled);
    }

    function setFeeRecipient(address recipient) external onlyOwner {
        _validRecipient(recipient);
        emit FeeRecipientChanged(feeRecipient, recipient);
        feeRecipient = recipient;
    }

    function _validateFactory(address factory) internal view override {
        if (IADDTokenFactoryV1(factory).portal() != address(this)
            || IADDTokenFactoryV1(factory).portalFactoryVersion() != 1) revert InvalidFactory();
    }

    /// @notice Called by an approved factory after creation and the token deposit.
    /// @dev Existing v13 factories do NOT implement this admission interface and
    ///      cannot be silently attached. New factory creation must be atomic.
    function registerFactoryToken(ADDAdmissionV1 calldata a) external nonReentrant {
        _requireFactory(msg.sender);
        if (!IADDTokenFactoryV1(msg.sender).isCreatedToken(a.token)
            || IADDTokenFactoryV1(msg.sender).creatorOf(a.token) != a.creator) revert InvalidAdmission();
        _admit(a, msg.sender, true);
    }

    /// @notice Owner explicitly starts a sale for already-deposited external tokens.
    /// @dev Merely transferring an ERC20 does not authorize it. The expected balance
    ///      binds this transaction to the owner's review and defeats donation-based
    ///      silent repricing before inclusion. No optional token hooks are trusted here.
    function registerExternalToken(ADDAdmissionV1 calldata a) external onlyOwner nonReentrant {
        if (a.lifecycleHooks) revert InvalidAdmission();
        _admit(a, address(0), true);
    }

    /// @notice Once explicitly opened by the owner, an external contract or wallet
    ///      may approve, deposit its own tokens, and start a sale atomically. No
    ///      prior factory allowlisting or second owner transaction is required.
    /// @dev Never adopts pre-existing unsolicited deposits or another pool's quote
    ///      reserves. Only the exact newly received amount forms this pool's 50/50
    ///      inventory. Standard/custom targets and all transfer checks still apply.
    function depositAndRegisterExternalToken(ADDExternalLaunchV1 calldata a) external nonReentrant {
        if (!externalDepositsEnabled) revert ExternalDepositsClosed();
        if (block.timestamp > a.deadline) revert TradeExpired();
        if (a.token.code.length == 0 || a.amount < 2) revert InvalidAdmission();
        if (pools[a.token].phase != Phase.Unlisted) revert AlreadyListed();
        if (IERC20Minimal(a.token).balanceOf(address(this)) < protectedERC20[a.token]) revert InsufficientBacking();
        _exactPull(a.token,msg.sender,a.amount);
        _admit(ADDAdmissionV1(a.token,msg.sender,a.quoteAsset,a.amount,a.targetBNB,a.quoteTarget,
            a.deadline,a.customTarget,false,a.metadataURI),address(0),false);
        emit ExternalDepositListed(a.token,msg.sender,a.amount);
    }

    function _admit(ADDAdmissionV1 memory a,address originFactory,bool useAllUnencumbered) internal {
        if (block.timestamp > a.deadline) revert TradeExpired();
        if (a.token.code.length == 0 || a.token == wrappedNative || a.token == a.quoteAsset
            || a.creator == address(0) || a.tokenDeposit < 2 || bytes(a.metadataURI).length > 2048) revert InvalidAdmission();
        if (pools[a.token].phase != Phase.Unlisted) revert AlreadyListed();
        if (a.customTarget) { if (!customTargetsEnabled) revert CustomTargetsClosed(); }
        else if (a.targetBNB != DEFAULT_TARGET_BNB) revert InvalidTarget();
        (uint256 target,uint8 decimals_) = quoteGraduationTarget(a.quoteAsset,a.targetBNB);
        if (target != a.quoteTarget) revert QuoteChanged();
        uint256 available = availableTokenSurplus(a.token);
        if (available < a.tokenDeposit || (useAllUnencumbered && available != a.tokenDeposit)) revert UnexpectedInventory();
        uint256 half = a.tokenDeposit / 2;
        // V2 reserves are uint112. These are protocol arithmetic limits, not a
        // configurable business cap. Reject impossible migrations at admission.
        if (half > type(uint112).max || target > type(uint112).max) revert InvalidAmount();
        address pairAsset = a.quoteAsset == address(0) ? wrappedNative : a.quoteAsset;
        address pair = IADDV2FactoryV1(dexFactory).getPair(a.token,pairAsset);
        if (pair == address(0)) pair = IADDV2FactoryV1(dexFactory).createPair(a.token,pairAsset);
        _checkPair(pair,a.token,pairAsset);
        if (IADDV2PairV1(pair).totalSupply() != 0) revert PoolAlreadyInitialized();
        pools[a.token] = Pool(originFactory,a.creator,a.quoteAsset,pair,a.tokenDeposit,half,half,0,0,
            a.targetBNB,target,decimals_,a.customTarget,a.lifecycleHooks,Phase.Active);
        // For odd deposits, one indivisible base unit is surplus; both halves are equal.
        protectedERC20[a.token] += 2 * half;
        if (a.lifecycleHooks) {
            if (IADDPortalTokenHooksV1(a.token).portal() != address(this)
                || IADDPortalTokenHooksV1(a.token).portalTokenVersion() != 1) revert InvalidAdmission();
            IADDPortalTokenHooksV1(a.token).onPortalAdmission(pair);
        }
        _assertPoolBacking(a.token);
        emit PoolRegistered(a.token,originFactory,a.creator,a.quoteAsset,pair,a.tokenDeposit,half,half,
            a.targetBNB,target,a.customTarget,a.metadataURI);
    }

    /// @notice Convert a BNB reference target to a fixed, whole quote-asset target.
    /// @dev The caller signs the returned value into admission. Current pool quotes
    ///      are NOT an oracle for economic value and remain subject to DEX movement.
    function quoteGraduationTarget(address asset,uint256 targetBNB) public view returns (uint256 target,uint8 decimals_) {
        return quoteHelper.quoteGraduationTarget(asset,targetBNB);
    }

    function _validateQuote(address asset) internal view returns (uint8) {
        return quoteHelper.validateQuoteAsset(asset);
    }

    function quoteBuy(address token,uint256 payment) public view returns (BuyQuote memory q) {
        Pool storage p = pools[token];
        if (p.phase != Phase.Active) revert PoolNotActive();
        (q.tokens,q.principal,q.nativeUsed,q.fee,q.refund) = quoteHelper.quoteBuy(
            payment,p.saleAllocation-p.sold,p.saleAllocation,p.quoteTarget,p.quoteAsset);
    }

    function quoteSell(address token,uint256 amount) public view returns (uint256 principal,uint256 gross,uint256 fee,uint256 net) {
        Pool storage p = pools[token];
        if (p.phase != Phase.Active) revert PoolNotActive();
        if (amount == 0 || amount > p.sold) revert InvalidAmount();
        return quoteHelper.quoteSell(amount,p.saleAllocation,p.quoteTarget,p.quoteAsset);
    }

    function availableNativeSurplus() public view returns (uint256) {
        return address(this).balance > totalNativeReserved ? address(this).balance - totalNativeReserved : 0;
    }
    function availableTokenSurplus(address token) public view returns (uint256) {
        uint256 balance = IERC20Minimal(token).balanceOf(address(this));
        return balance > protectedERC20[token] ? balance - protectedERC20[token] : 0;
    }
    function withdrawBNB(address payable recipient,uint256 amount) external onlyOwner nonReentrant {
        _validRecipient(recipient);
        if (amount == 0 || amount > availableNativeSurplus()) revert InsufficientSurplus();
        _send(recipient,amount);
        if (address(this).balance < totalNativeReserved) revert InsufficientBacking();
        emit SurplusWithdrawn(address(0),recipient,amount);
    }
    /// @dev Recovery of an unknown token need not guarantee the recipient's exact
    ///      net amount, but even a transfer fee cannot consume protected inventory.
    function withdrawToken(address token,address recipient,uint256 amount) external onlyOwner nonReentrant {
        _validRecipient(recipient);
        if (amount == 0 || amount > availableTokenSurplus(token)) revert InsufficientSurplus();
        IERC20Minimal(token).safeTransfer(recipient,amount);
        if (IERC20Minimal(token).balanceOf(address(this)) < protectedERC20[token]) revert InsufficientBacking();
        emit SurplusWithdrawn(token,recipient,amount);
    }

    function _assertPoolBacking(address token) internal view {
        this.assertPoolBacking(token);
    }
    /// @notice Read-only coverage check shared by every guarded settlement flow.
    function assertPoolBacking(address token) external view {
        if (address(this).balance < totalNativeReserved
            || IERC20Minimal(token).balanceOf(address(this)) < protectedERC20[token]) revert InsufficientBacking();
        address asset = pools[token].quoteAsset;
        if (asset != address(0) && IERC20Minimal(asset).balanceOf(address(this)) < protectedERC20[asset]) revert InsufficientBacking();
    }
    function _checkPair(address pair,address a,address b) internal view {
        if (pair.code.length == 0) revert InvalidPair();
        address t0 = IADDV2PairV1(pair).token0();
        address t1 = IADDV2PairV1(pair).token1();
        if (!((t0 == a && t1 == b) || (t0 == b && t1 == a))) revert InvalidPair();
    }
    function _path(address asset,bool buying) internal view returns (address[] memory route) {
        route = new address[](2);
        route[0] = buying ? wrappedNative : asset;
        route[1] = buying ? asset : wrappedNative;
    }
    function _approve(address asset,uint256 amount) internal {
        this.executeApproval(asset,router,amount);
    }
    /// @dev Self-only primitives execute inside a nonReentrant outer operation.
    ///      The shared bodies avoid duplicating token-call validation in runtime code.
    function executeApproval(address asset,address spender,uint256 amount) external {
        if (msg.sender != address(this)) revert OnlySelf();
        IERC20Minimal(asset).safeApprove(spender,0);
        if (amount != 0) IERC20Minimal(asset).safeApprove(spender,amount);
    }
    function _exactTransfer(address asset,address recipient,uint256 amount) internal {
        this.executeExactTransfer(asset,recipient,amount);
    }
    function executeExactTransfer(address asset,address recipient,uint256 amount) external {
        if (msg.sender != address(this)) revert OnlySelf();
        uint256 fromBefore = IERC20Minimal(asset).balanceOf(address(this));
        uint256 toBefore = IERC20Minimal(asset).balanceOf(recipient);
        IERC20Minimal(asset).safeTransfer(recipient,amount);
        if (IERC20Minimal(asset).balanceOf(address(this)) + amount != fromBefore
            || IERC20Minimal(asset).balanceOf(recipient) != toBefore + amount) revert UnsupportedTransfer();
    }
    function _exactPull(address asset,address sender,uint256 amount) internal {
        this.executeExactPull(asset,sender,amount);
    }
    function executeExactPull(address asset,address sender,uint256 amount) external {
        if (msg.sender != address(this)) revert OnlySelf();
        uint256 beforeBalance = IERC20Minimal(asset).balanceOf(address(this));
        IERC20Minimal(asset).safeTransferFrom(sender,address(this),amount);
        if (IERC20Minimal(asset).balanceOf(address(this)) != beforeBalance + amount) revert UnsupportedTransfer();
    }
    function _send(address recipient,uint256 amount) internal {
        if (amount == 0) return;
        (bool ok,) = payable(recipient).call{value:amount}("");
        if (!ok) revert NativeTransferFailed();
    }
    function _validRecipient(address recipient) internal view {
        if (recipient == address(0) || recipient == address(this)) revert InvalidRecipient();
    }
}

contracts/portal-v1/ADDPortalLiquidityV1.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ADDPortalLedgerV1.sol";
import "./ADDPortalConversionV1.sol";

/// @notice Candidate migration mechanics, independent of the graduation trigger.
/// @dev The concrete eligibility policy is deliberately a separate override. This
///      abstract module is NOT a deployable Portal or an authorization to graduate.
abstract contract ADDPortalLiquidityV1 is ADDPortalLedgerV1 {
    using SafeERC20 for IERC20Minimal;
    ADDPortalConversionV1 public immutable recoveryConverter;
    error NotReadyToGraduate();
    error InvalidLiquidity();
    error InsufficientMigrationGas();
    event GraduationFailed(address indexed token,bytes4 reasonSelector);
    event Graduated(address indexed token,address indexed pair,address quoteAsset,
        uint256 tokensAdded,uint256 quoteAdded,uint256 lpBurned,uint256 unsoldRetained);

    // Original quoteAsset/quoteTarget remain the immutable fundraising denomination.
    // These fields record the actual successful settlement, which may be different.
    struct Settlement { address quoteAsset; uint256 quoteAmount; }
    mapping(address => Settlement) public graduationSettlement;

    constructor(address owner_,address router_,address feeRecipient_,bool customEnabled)
        ADDPortalLedgerV1(owner_,router_,feeRecipient_,customEnabled) {
        recoveryConverter = new ADDPortalConversionV1(router_);
    }

    function canGraduate(address token) public view returns (bool) {
        Pool storage p = pools[token];
        return (p.phase == Phase.Active || p.phase == Phase.GraduationFailed)
            && p.reserve > 0 && _graduationEligible(p);
    }

    /// @notice Anyone may pay gas to finish an eligible pool; callers cannot choose
    ///      the amounts, recipient, pair or price and receive no assets or bounty.
    function graduate(address token) external nonReentrant {
        if (!canGraduate(token)) revert NotReadyToGraduate();
        _attemptGraduation(token);
    }

    function _afterBuy(address token) internal {
        if (canGraduate(token)) _attemptGraduation(token);
    }

    /// @dev Only entered by a guarded buy/graduate via this contract's self-call.
    ///      A separate call frame lets migration roll back WITHOUT undoing the final
    ///      purchase, its token delivery, fee, and excess-payment refund.
    function executeGraduation(address token) external {
        if (msg.sender != address(this)) revert OnlySelf();
        if (!canGraduate(token)) revert NotReadyToGraduate();
        _graduate(token);
    }

    function _attemptGraduation(address token) internal {
        bytes memory payload = abi.encodeCall(this.executeGraduation,(token));
        // Keep gas for recording failure and the outer ledger's backing checks.
        // Do not copy arbitrary revert bytes from untrusted external token hooks.
        uint256 available = gasleft();
        if (available < 250000) revert InsufficientMigrationGas();
        uint256 forwarded = available - 150000;
        bool success;
        bytes4 reason;
        assembly ("memory-safe") {
            success := call(forwarded,address(),0,add(payload,32),mload(payload),0,0)
            if iszero(success) {
                let scratch := mload(0x40)
                mstore(scratch,0)
                if gt(returndatasize(),3) { returndatacopy(scratch,0,4) }
                reason := mload(scratch)
            }
        }
        if (!success) {
            pools[token].phase = Phase.GraduationFailed;
            emit GraduationFailed(token,reason);
        }
        // A failed attempt is not proof of permanent failure: it may be transient
        // or gas-related. Anyone may retry the original pair using graduate().
    }

    function _graduate(address token) internal {
        Pool storage p = pools[token];
        _assertPoolBacking(token);
        uint256 reserve = p.reserve;
        address quoteAsset = p.quoteAsset;
        _requireEmptyPair(p.pair,token,quoteAsset);
        _beginGraduation(token,p.pair);
        if (quoteAsset == address(0)) _wrapNative(reserve);
        _supplyLiquidity(token,quoteAsset,reserve);
    }

    function _requireEmptyPair(address pair,address token,address quoteAsset) internal view {
        address asset = quoteAsset == address(0) ? wrappedNative : quoteAsset;
        // Arbitrary external tokens can trade before admission or permit somebody
        // to initialize this pair early. Never donate customer reserves to existing
        // LP owners. Such a token is NOT compatible with this migration protocol.
        recoveryConverter.assertEmptyPair(token,asset,pair);
    }

    /// @dev Called inside the same atomic frame as conversion and LP minting.
    ///      Only this project's obligations are released; every failure restores them.
    function _beginGraduation(address token,address pair) internal {
        Pool storage p = pools[token];
        uint256 reserve = p.reserve;
        p.phase = Phase.Migrating;
        p.pair = pair;
        p.reserve = 0;
        // Release only THIS sale's obligations. Unsold sale units physically stay
        // in Portal as surplus; the original LP half alone goes to the pair.
        protectedERC20[token] -= p.liquidityAllocation + p.saleAllocation - p.sold;
        if (p.quoteAsset == address(0)) totalNativeReserved -= reserve;
        else protectedERC20[p.quoteAsset] -= reserve;
        if (p.lifecycleHooks) IADDPortalTokenHooksV1(token).onPortalMigrationStart(pair);
    }

    function _wrapNative(uint256 amount) internal {
        uint256 beforeWrapped = IERC20Minimal(wrappedNative).balanceOf(address(this));
        IADDWrappedNativeV1(wrappedNative).deposit{value:amount}();
        if (IERC20Minimal(wrappedNative).balanceOf(address(this)) != beforeWrapped + amount) revert UnsupportedTransfer();
    }

    /// @dev For native settlement, caller has already wrapped this project's BNB.
    ///      Recheck the pair after all hooks/swaps, before delivering any LP assets.
    function _supplyLiquidity(address token,address quoteAsset,uint256 reserve) internal {
        Pool storage p = pools[token];
        address asset = quoteAsset == address(0) ? wrappedNative : quoteAsset;
        uint256 lpInventory = p.liquidityAllocation;
        this.executeApproval(asset,address(recoveryConverter),reserve);
        this.executeApproval(token,address(recoveryConverter),lpInventory);
        uint256 liquidity = recoveryConverter.mintLiquidity(token,asset,p.pair,lpInventory,reserve);
        this.executeApproval(asset,address(recoveryConverter),0);
        this.executeApproval(token,address(recoveryConverter),0);
        p.phase = Phase.Graduated;
        graduationSettlement[token] = Settlement(quoteAsset,reserve);
        if (p.lifecycleHooks) IADDPortalTokenHooksV1(token).onPortalGraduation();
        _assertPoolBacking(token);
        if (IERC20Minimal(asset).balanceOf(address(this)) < protectedERC20[asset]) revert InsufficientBacking();
        emit Graduated(token,p.pair,quoteAsset,lpInventory,reserve,liquidity,p.saleAllocation-p.sold);
    }

    function _graduationEligible(Pool storage p) internal view virtual returns (bool);
}

contracts/portal-v1/ADDPortalQuoterV1.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./IADDPortalV1.sol";
import "./ADDFixedPriceMathV1.sol";
import "../openzeppelin/SafeERC20.sol";

/// @notice Immutable, read-only pricing module automatically deployed with Portal.
/// @dev Never holds, approves or transfers funds. Only the Portal ledger supplies
///      authoritative inventory/state; this module performs the existing V1 maths.
contract ADDPortalQuoterV1 {
    address public immutable router;
    address public immutable wrappedNative;
    address public immutable dexFactory;
    error InvalidTarget();
    error UnsupportedAsset();
    error InvalidPair();
    error InvalidAmount();
    error SlippageExceeded();
    constructor(address router_) {
        router = router_;
        wrappedNative = IADDV2RouterV1(router_).WETH();
        dexFactory = IADDV2RouterV1(router_).factory();
    }
    function validateQuoteAsset(address asset) public view returns (uint8 decimals_) {
        if (asset.code.length == 0 || asset == wrappedNative) revert UnsupportedAsset();
        (bool ok,bytes memory data) = asset.staticcall{gas:30000}(abi.encodeWithSignature("decimals()"));
        if (!ok || data.length != 32 || abi.decode(data,(uint256)) > 36) revert UnsupportedAsset();
        decimals_ = uint8(abi.decode(data,(uint256)));
        address pair = IADDV2FactoryV1(dexFactory).getPair(asset,wrappedNative);
        if (pair.code.length == 0) revert InvalidPair();
        address a = IADDV2PairV1(pair).token0();
        address b = IADDV2PairV1(pair).token1();
        if (!((a == asset && b == wrappedNative) || (b == asset && a == wrappedNative))) revert InvalidPair();
        (uint112 r0,uint112 r1,) = IADDV2PairV1(pair).getReserves();
        if (r0 == 0 || r1 == 0) revert UnsupportedAsset();
    }
    function quoteGraduationTarget(address asset,uint256 targetBNB) external view returns (uint256 target,uint8 decimals_) {
        if (targetBNB < 1 ether) revert InvalidTarget();
        if (asset == address(0)) return (targetBNB,18);
        decimals_ = validateQuoteAsset(asset);
        uint256 quoted = IADDV2RouterV1(router).getAmountsOut(targetBNB,_path(asset,true))[1];
        if (quoted == 0) revert InvalidTarget();
        uint256 unit = 10 ** uint256(decimals_);
        target = FullMath.mulDivUp(quoted,1,unit) * unit;
    }
    function quoteBuy(uint256 payment,uint256 remaining,uint256 saleAllocation,uint256 quoteTarget,address asset)
        external view returns (uint256 tokens,uint256 principal,uint256 nativeUsed,uint256 fee,uint256 refund)
    {
        if (asset == address(0)) {
            (tokens,principal,fee,refund) = ADDFixedPriceMathV1.quoteNativeBuy(payment,remaining,saleAllocation,quoteTarget);
            nativeUsed = principal;
        } else {
            if (payment == 0 || remaining == 0) return (0,0,0,0,payment);
            uint256 budget = payment - payment / 100;
            uint256 quoted = IADDV2RouterV1(router).getAmountsOut(budget,_path(asset,true))[1];
            uint256 remainingCost = ADDFixedPriceMathV1.costUp(remaining,saleAllocation,quoteTarget);
            tokens = quoted >= remainingCost ? remaining : FullMath.mulDiv(quoted,saleAllocation,quoteTarget);
            if (tokens == 0) return (0,0,0,0,payment);
            principal = ADDFixedPriceMathV1.costUp(tokens,saleAllocation,quoteTarget);
            nativeUsed = IADDV2RouterV1(router).getAmountsIn(principal,_path(asset,true))[0];
            if (nativeUsed > budget) revert SlippageExceeded();
            fee = nativeUsed == budget ? payment / 100 : nativeUsed / 99;
            refund = payment - nativeUsed - fee;
        }
    }
    function quoteSell(uint256 amount,uint256 saleAllocation,uint256 quoteTarget,address asset)
        external view returns (uint256 principal,uint256 gross,uint256 fee,uint256 net)
    {
        principal = ADDFixedPriceMathV1.valueDown(amount,saleAllocation,quoteTarget);
        if (principal == 0) revert InvalidAmount();
        gross = asset == address(0) ? principal : IADDV2RouterV1(router).getAmountsOut(principal,_path(asset,false))[1];
        fee = gross / 100;
        net = gross - fee;
    }
    function _path(address asset,bool buying) internal view returns (address[] memory route) {
        route = new address[](2);
        route[0] = buying ? wrappedNative : asset;
        route[1] = buying ? asset : wrappedNative;
    }
}

contracts/portal-v1/ADDPortalRecoveryV1..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ADDPortalLiquidityV1.sol";
import "./ADDPortalConversionV1.sol";

/// @notice Owner-directed recovery of a paused, failed graduation. No funds can
///         be sent to the owner: settlement is either burned LP or holder refunds.
/// @dev The owner chooses the replacement quote asset and signs its output quote.
///      This is a meaningful trust assumption. A 5% execution tolerance is NOT an
///      oracle or a guarantee of economic value for an arbitrary ERC20. Review the
///      asset and its liquidity independently; ordinary spot quotes can be manipulated.
abstract contract ADDPortalRecoveryV1 is ADDPortalLiquidityV1 {
    using SafeERC20 for IERC20Minimal;
    uint256 public constant RECOVERY_SLIPPAGE_BPS = 500;
    // Original unsold sale allocation + LP allocation stay protected during refunds.
    mapping(address => uint256) public refundInventory;

    error NotFailedGraduation();
    error InvalidRecoveryAsset();
    error RecoveryQuoteChanged();
    error RefundsNotEnabled();
    error OnlyRecoveryConverter();

    event AlternativeGraduation(address indexed token,address indexed oldQuoteAsset,
        address indexed newQuoteAsset,address pair,uint256 amountIn,uint256 amountOut,uint256 minimumOut);
    event RefundsEnabled(address indexed token,address indexed quoteAsset,uint256 tokensOutstanding,uint256 reserve);
    event Refunded(address indexed token,address indexed holder,address quoteAsset,uint256 tokensReturned,uint256 assetsReturned);
    event RefundsCompleted(address indexed token,uint256 unissuedTokensBurned);

    constructor(address owner_,address router_,address feeRecipient_,bool customEnabled)
        ADDPortalLiquidityV1(owner_,router_,feeRecipient_,customEnabled) {}

    /// @notice Preview a full-reserve exact-input conversion using the fixed router.
    ///         Zero replacement address means BNB/WBNB settlement. The signed amountIn
    ///         binds the owner transaction to the reviewed project reserve.
    function quoteAlternativeGraduation(address token,address newQuoteAsset) public view
        returns (uint256 amountIn,uint256 expectedOut,uint256 minimumOut,address[] memory path)
    {
        _requireFailed(token);
        Pool storage p = pools[token];
        if (newQuoteAsset == p.quoteAsset || newQuoteAsset == token || newQuoteAsset == wrappedNative)
            revert InvalidRecoveryAsset();
        if (newQuoteAsset != address(0)) _validateQuote(newQuoteAsset);
        amountIn = p.reserve;
        (expectedOut,minimumOut,path) = recoveryConverter.quote(p.quoteAsset,newQuoteAsset,amountIn);
    }

    /// @notice Spend only this failed project's ENTIRE reserve, receive the chosen
    ///         asset, then pair ALL actual output with the original LP token half.
    ///         No additional ADD platform fee. Router fees and price impact apply.
    /// @param quotedOut Output reviewed off-chain and signed by the owner. Never zero.
    /// @dev The effective minimum is the stricter of 95% of the signed quote and
    ///      95% of the current router quote. Raising slippage above 5% is impossible.
    ///      All conversion, hooks, bookkeeping and LP minting share one transaction:
    ///      ANY failure restores the original asset/reserve, approval and paused state.
    function graduateWithAlternativeAsset(address token,address newQuoteAsset,
        uint256 expectedReserve,uint256 quotedOut,uint256 deadline) external onlyOwner nonReentrant
    {
        if (block.timestamp > deadline) revert TradeExpired();
        if (quotedOut == 0) revert InvalidAmount();
        _requireFailed(token);
        if (pools[token].reserve != expectedReserve) revert RecoveryQuoteChanged();
        (uint256 received,uint256 minimumOut) = recoveryConverter.graduateAlternative(token,newQuoteAsset,expectedReserve,quotedOut,deadline);
        Pool storage p = pools[token];
        emit AlternativeGraduation(token,p.quoteAsset,newQuoteAsset,p.pair,expectedReserve,received,minimumOut);
    }

    /// @dev Fixed helper callback within the owner entry's reentrancy lock.
    ///      Verify the proposed pair belongs to the immutable factory, then release
    ///      only this project's reserve and approve exactly that amount to the helper.
    function executeRecoveryStart(address token,address pair,uint256 reserve) external {
        if (msg.sender != address(recoveryConverter)) revert OnlyRecoveryConverter();
        _requireFailed(token);
        if (pools[token].reserve != reserve) revert RecoveryQuoteChanged();
        _assertPoolBacking(token);
        Pool storage p = pools[token];
        address oldQuoteAsset = p.quoteAsset;
        address a = IADDV2PairV1(pair).token0();
        address b = IADDV2PairV1(pair).token1();
        address outputAsset = a == token ? b : a;
        if (IADDV2FactoryV1(dexFactory).getPair(token,outputAsset) != pair) revert InvalidPair();
        _requireEmptyPair(pair,token,outputAsset);
        _beginGraduation(token,pair);
        if (oldQuoteAsset == address(0)) _wrapNative(reserve);
        address input = oldQuoteAsset == address(0) ? wrappedNative : oldQuoteAsset;
        this.executeApproval(input,address(recoveryConverter),reserve);
    }

    function executeRecoveryFinish(address token,address newQuoteAsset,uint256 received) external {
        if (msg.sender != address(recoveryConverter)) revert OnlyRecoveryConverter();
        Pool storage p = pools[token];
        if (p.phase != Phase.Migrating) revert NotFailedGraduation();
        address input = p.quoteAsset == address(0) ? wrappedNative : p.quoteAsset;
        this.executeApproval(input,address(recoveryConverter),0);
        if (IERC20Minimal(input).balanceOf(address(this)) < protectedERC20[input]) revert InsufficientBacking();
        _supplyLiquidity(token,newQuoteAsset,received);
    }

    function _requireFailed(address token) internal view {
        if (pools[token].phase != Phase.GraduationFailed || !canGraduate(token)) revert NotFailedGraduation();
    }

    /// @notice Irreversibly abandon graduation and allow holder-initiated refunds.
    ///         Owner cannot choose refund recipients, withdraw backing, resume sales,
    ///         or switch assets after this decision. Owner action is required; there
    ///         is no automatic timeout, so availability depends on owner cooperation.
    function enableRefunds(address token) external onlyOwner nonReentrant {
        _requireFailed(token);
        _assertPoolBacking(token);
        Pool storage p = pools[token];
        refundInventory[token] = p.saleAllocation + p.liquidityAllocation - p.sold;
        p.phase = Phase.RefundOnly;
        if (p.lifecycleHooks) IADDPortalTokenHooksV1(token).onPortalRefundStart();
        emit RefundsEnabled(token,p.quoteAsset,p.sold,p.reserve);
    }

    /// @notice Pro-rata ORIGINAL quote-asset units, not a new BNB conversion.
    ///         Past trading fees are not refundable; no new fee is charged. The
    ///         last outstanding claim receives rounding dust so no reserve is stranded.
    function quoteRefund(address token,uint256 amount) public view returns (uint256 assets) {
        Pool storage p = pools[token];
        if (p.phase != Phase.RefundOnly) revert RefundsNotEnabled();
        if (amount == 0 || amount > p.sold) revert InvalidAmount();
        assets = amount == p.sold ? p.reserve : FullMath.mulDiv(p.reserve,amount,p.sold);
        if (assets == 0) revert InvalidAmount();
    }

    /// @notice Holder approves and returns fungible tokens, receiving their share
    ///         directly. Returned tokens go to dead to prevent repeat claims. This
    ///         is not a historical-wallet reimbursement: a transferee can redeem.
    function refund(address token,uint256 amount,uint256 minimumAssets,uint256 deadline)
        external nonReentrant returns (uint256 assets)
    {
        if (block.timestamp > deadline) revert TradeExpired();
        _assertPoolBacking(token);
        assets = quoteRefund(token,amount);
        if (assets < minimumAssets) revert SlippageExceeded();
        Pool storage p = pools[token];
        p.sold -= amount;
        p.reserve -= assets;
        if (p.quoteAsset == address(0)) totalNativeReserved -= assets;
        else protectedERC20[p.quoteAsset] -= assets;
        _exactPull(token,msg.sender,amount);
        _exactTransfer(token,LP_BURN_ADDRESS,amount);
        if (p.quoteAsset == address(0)) _send(msg.sender,assets);
        else _exactTransfer(p.quoteAsset,msg.sender,assets);
        emit Refunded(token,msg.sender,p.quoteAsset,amount,assets);
        if (p.sold == 0) {
            uint256 inventory = refundInventory[token];
            refundInventory[token] = 0;
            p.phase = Phase.Refunded;
            protectedERC20[token] -= inventory;
            // Unissued project inventory cannot be recirculated by the owner during
            // refunds. Dispose of it only when all outstanding claims are settled.
            if (inventory != 0) _exactTransfer(token,LP_BURN_ADDRESS,inventory);
            if (p.lifecycleHooks) IADDPortalTokenHooksV1(token).onPortalRefundComplete();
            emit RefundsCompleted(token,inventory);
        }
        _assertPoolBacking(token);
    }
}

contracts/portal-v1/ADDPortalTradeModule.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ADDPortalLedgerV1.sol";
interface IADDTradeHostV1 { function executeAfterBuy(address token) external; }

/// @notice Fixed trade implementation shared by immutable V1 Portals.
/// @dev Portal stores the module address immutably and delegates ONLY buy/sell.
///      This module and the host must inherit IDENTICAL ADDPortalLedgerV1 storage;
///      no upgrade setter exists. Deploy this module first, then pass its address
///      to the Portal constructor. Direct buy/sell on the module are forbidden.
contract ADDPortalTradeModuleV1 is ADDPortalLedgerV1 {
    address private immutable moduleAddress;
    error OnlyDelegateCall();
    constructor(address router_) ADDPortalLedgerV1(msg.sender,router_,msg.sender,false) {
        moduleAddress = address(this);
    }
    modifier onlyDelegate() {
        if (address(this) == moduleAddress) revert OnlyDelegateCall();
        _;
    }
    function buy(address token,uint256 minimumTokens,uint256 deadline) external payable onlyDelegate nonReentrant returns (uint256) {
        if (block.timestamp > deadline) revert TradeExpired();
        if (pools[token].phase != Phase.Active) revert PoolNotActive();
        if (address(this).balance - msg.value < totalNativeReserved) revert InsufficientBacking();
        _assertPoolBacking(token);
        BuyQuote memory q = quoteBuy(token,msg.value);
        if (q.tokens == 0) revert InvalidAmount();
        if (q.tokens < minimumTokens) revert SlippageExceeded();
        Pool storage p = pools[token];
        p.sold += q.tokens;
        p.reserve += q.principal;
        protectedERC20[token] -= q.tokens;
        if (p.quoteAsset == address(0)) totalNativeReserved += q.principal;
        else {
            uint256 beforeAsset = IERC20Minimal(p.quoteAsset).balanceOf(address(this));
            uint256[] memory spent = IADDV2RouterV1(router).swapETHForExactTokens{value:q.nativeUsed}(
                q.principal,_path(p.quoteAsset,true),address(this),deadline);
            if (spent.length != 2 || spent[0] != q.nativeUsed || spent[1] != q.principal
                || IERC20Minimal(p.quoteAsset).balanceOf(address(this)) != beforeAsset + q.principal) revert UnsupportedTransfer();
            protectedERC20[p.quoteAsset] += q.principal;
        }
        _exactTransfer(token,msg.sender,q.tokens);
        _send(feeRecipient,q.fee);
        _send(msg.sender,q.refund);
        emit Buy(token,msg.sender,msg.value,q.tokens,q.principal,q.nativeUsed,q.fee,q.refund);
        IADDTradeHostV1(address(this)).executeAfterBuy(token);
        _assertPoolBacking(token);
        return q.tokens;
    }

    function sell(address token,uint256 amount,uint256 minimumBNB,uint256 deadline) external onlyDelegate nonReentrant returns (uint256 net) {
        if (block.timestamp > deadline) revert TradeExpired();
        if (pools[token].phase != Phase.Active) revert PoolNotActive();
        _assertPoolBacking(token);
        (uint256 principal,uint256 gross,,) = quoteSell(token,amount);
        Pool storage p = pools[token];
        if (principal > p.reserve) revert InsufficientBacking();
        p.sold -= amount;
        p.reserve -= principal;
        protectedERC20[token] += amount;
        if (p.quoteAsset == address(0)) totalNativeReserved -= principal;
        else protectedERC20[p.quoteAsset] -= principal;
        _exactPull(token,msg.sender,amount);
        if (p.quoteAsset != address(0)) {
            uint256 beforeAsset = IERC20Minimal(p.quoteAsset).balanceOf(address(this));
            uint256 beforeBNB = address(this).balance;
            _approve(p.quoteAsset,principal);
            uint256[] memory received = IADDV2RouterV1(router).swapExactTokensForETH(
                principal,minimumBNB,_path(p.quoteAsset,false),address(this),deadline);
            _approve(p.quoteAsset,0);
            gross = address(this).balance - beforeBNB;
            if (received.length != 2 || received[0] != principal || received[1] != gross
                || IERC20Minimal(p.quoteAsset).balanceOf(address(this)) + principal != beforeAsset) revert UnsupportedTransfer();
        }
        uint256 fee = gross / 100;
        net = gross - fee;
        if (net == 0) revert InvalidAmount();
        if (net < minimumBNB) revert SlippageExceeded();
        _send(feeRecipient,fee);
        _send(msg.sender,net);
        emit Sell(token,msg.sender,amount,principal,gross,fee,net);
        _assertPoolBacking(token);
    }

}

contracts/portal-v1/ADDPortalV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "./ADDPortalRecoveryV1.sol";
import "./ADDPortalTradeModuleV1.sol";

/// @title ADD Portal v1 candidate: variable inventory and surplus-only recovery.
/// @notice Standard reference target is 4 BNB. Custom targets start at 1 BNB.
///         Half of the admitted inventory is sold at a fixed ratio; the original
///         other half and actual reserves are added to V2 when unsold sale units
///         fall STRICTLY BELOW 1% of the original admitted inventory.
/// @dev With even inventory this means strictly more than 98% of the sale half
///      is sold. The full reference target need not be reached. No proxy or upgrade
///      route exists. Existing v13 tokens/factories are not migrated by deployment.
contract ADDPortalV1 is ADDPortalRecoveryV1 {
    address public immutable tradeModule;
    error InvalidTradeModule();

    constructor(address owner_,address router_,address feeRecipient_,bool customEnabled,address tradeModule_)
        ADDPortalRecoveryV1(owner_,router_,feeRecipient_,customEnabled) {
        if (tradeModule_.code.length == 0 || ADDPortalTradeModuleV1(payable(tradeModule_)).router() != router_
            || ADDPortalTradeModuleV1(payable(tradeModule_)).DEPLOYMENT_VERSION() != 1) revert InvalidTradeModule();
        tradeModule = tradeModule_;
    }

    /// @dev Fixed selector dispatch, NOT an upgradeable proxy or an arbitrary-call
    ///      facility. The implementation enforces nonReentrant in the same ledger
    ///      storage. Deployment must verify the audited module bytecode, not just ABI.
    function buy(address,uint256,uint256) external payable returns (uint256) { _delegateTrade(); }
    function sell(address,uint256,uint256,uint256) external returns (uint256) { _delegateTrade(); }
    function _delegateTrade() private {
        address implementation = tradeModule;
        assembly ("memory-safe") {
            let ptr := mload(0x40)
            calldatacopy(ptr,0,calldatasize())
            let success := delegatecall(gas(),implementation,ptr,calldatasize(),0,0)
            returndatacopy(ptr,0,returndatasize())
            switch success
            case 0 { revert(ptr,returndatasize()) }
            default { return(ptr,returndatasize()) }
        }
    }
    /// @dev Called only by the fixed trade module executing in Portal's context.
    function executeAfterBuy(address token) external {
        if (msg.sender != address(this)) revert OnlySelf();
        _afterBuy(token);
    }

    function _graduationEligible(Pool storage p) internal view override returns (bool) {
        // Avoid a rounded-down threshold: for tiny/odd inventories compare the
        // exact ratio. Admission caps half at uint112, so multiplication is safe.
        return (p.saleAllocation - p.sold) * 100 < p.initialInventory;
    }
}

contracts/portal-v1/IADDPortalV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @notice Admission data signed as part of the factory or owner transaction.
/// @dev BNB targets use wei; tokenDeposit and quoteTarget use their own ERC20 base
///      units. A quote target is snapshotted, so later BNB/USDT exchange-rate changes
///      do not reprice an active sale. Metadata is an opaque URI, never executable.
struct ADDAdmissionV1 {
    address token;
    address creator;
    address quoteAsset; // address(0) = native BNB; native buys/sells remain available for ERC20 quotes.
    uint256 tokenDeposit; // Expected unencumbered balance ALREADY held by Portal.
    uint256 targetBNB;
    uint256 quoteTarget; // Expected asset target from Portal.quoteGraduationTarget.
    uint256 deadline;
    bool customTarget;
    bool lifecycleHooks;
    string metadataURI;
}

/// @notice Opt-in public external deposit. The caller becomes the recorded creator;
///         Portal pulls only this caller's approved amount in the same transaction.
struct ADDExternalLaunchV1 {
    address token;
    uint256 amount;
    address quoteAsset;
    uint256 targetBNB;
    uint256 quoteTarget;
    uint256 deadline;
    bool customTarget;
    string metadataURI;
}

interface IADDPortalAdmissionV1 {
    function registerFactoryToken(ADDAdmissionV1 calldata admission) external;
    function depositAndRegisterExternalToken(ADDExternalLaunchV1 calldata launch) external;
    function quoteGraduationTarget(address asset, uint256 targetBNB) external view returns (uint256 target, uint8 decimals_);
}

/// @notice Only owner-approved factories implementing this interface may auto-admit tokens.
/// @dev A factory must set its creation record BEFORE calling registerFactoryToken,
///      in the SAME transaction as creation/deposit. These getters are attestations
///      from a trusted, reviewed factory, not cryptographic proof of arbitrary code.
interface IADDTokenFactoryV1 {
    function portal() external view returns (address);
    function portalFactoryVersion() external pure returns (uint256);
    function isCreatedToken(address token) external view returns (bool);
    function creatorOf(address token) external view returns (address);
}

/// @notice Optional hooks for new compatible ADD tokens. Plain externally listed
///         ERC20s use lifecycleHooks=false and receive no lifecycle calls.
interface IADDPortalTokenHooksV1 {
    function portal() external view returns (address);
    function portalTokenVersion() external pure returns (uint256);
    function onPortalAdmission(address pair) external;
    function onPortalMigrationStart(address pair) external;
    function onPortalGraduation() external;
    function onPortalRefundStart() external;
    function onPortalRefundComplete() external;
}

interface IADDV2RouterV1 {
    function factory() external view returns (address);
    function WETH() external view returns (address);
    function getAmountsOut(uint256 amount, address[] calldata path) external view returns (uint256[] memory);
    function getAmountsIn(uint256 amount, address[] calldata path) external view returns (uint256[] memory);
    function swapETHForExactTokens(uint256 amountOut,address[] calldata path,address to,uint256 deadline) external payable returns (uint256[] memory);
    function swapExactTokensForETH(uint256 amountIn,uint256 minOut,address[] calldata path,address to,uint256 deadline) external returns (uint256[] memory);
    function swapExactTokensForTokens(uint256 amountIn,uint256 minOut,address[] calldata path,address to,uint256 deadline) external returns (uint256[] memory);
}

interface IADDV2FactoryV1 {
    function getPair(address a, address b) external view returns (address);
    function createPair(address a, address b) external returns (address);
}

interface IADDV2PairV1 {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function getReserves() external view returns (uint112,uint112,uint32);
    function mint(address recipient) external returns (uint256);
}

interface IADDWrappedNativeV1 {
    function deposit() external payable;
}
